package com.puzzledrops.compassquadrants;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CompassQuadrantsConfig.GROUP)
public interface CompassQuadrantsConfig extends Config
{
	String GROUP = "compass-quadrants";

	@ConfigItem(
		keyName = "rotateWithCompass",
		name = "Wedges follow the compass",
		description = "Click where the direction actually appears on the compass. When off, the top wedge is always north regardless of how the compass is rotated.",
		position = 1
	)
	default boolean rotateWithCompass()
	{
		return true;
	}

	@ConfigItem(
		keyName = "wedgeGuides",
		name = "Show wedge guides",
		description = "When to draw the lines dividing the compass into wedges. Always keeps them on screen permanently.",
		position = 2
	)
	default WedgeGuideMode wedgeGuides()
	{
		return WedgeGuideMode.NEVER;
	}

	@ConfigItem(
		keyName = "highlightHoveredWedge",
		name = "Highlight hovered wedge",
		description = "Shade the wedge under the mouse. Works independently of the dividing lines, so you can have one without the other.",
		position = 3
	)
	default boolean highlightHoveredWedge()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "guideColor",
		name = "Divider colour",
		description = "Colour of the lines splitting the compass into wedges",
		position = 4
	)
	default Color guideColor()
	{
		return new Color(0xC8FFFFFF, true);
	}

	@Alpha
	@ConfigItem(
		keyName = "highlightColor",
		name = "Hover colour",
		description = "Colour used to shade the wedge under the mouse",
		position = 5
	)
	default Color highlightColor()
	{
		return new Color(0xC8FFFFFF, true);
	}

	@ConfigItem(
		keyName = "showCompassLetters",
		name = "Draw compass letters",
		description = "Erase the game's own N and draw all four letters instead, so they match. They label the wedges, so they hold still whenever the wedges do.",
		position = 6
	)
	default boolean showCompassLetters()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "northLetterColor",
		name = "North letter colour",
		description = "Colour of the N, kept separate so north stands out from the other three",
		position = 7
	)
	default Color northLetterColor()
	{
		return new Color(0xFF640000, true);
	}

	@Alpha
	@ConfigItem(
		keyName = "letterColor",
		name = "Other letter colour",
		description = "Colour of the E, S and W letters",
		position = 8
	)
	default Color letterColor()
	{
		return new Color(0xFF000000, true);
	}

	@Alpha
	@ConfigItem(
		keyName = "northMarkerColor",
		name = "North slice colour",
		description = "Colour of the slice on the rim marking true north. Only shown when the wedges do not follow the compass.",
		position = 9
	)
	default Color northMarkerColor()
	{
		return new Color(0xFFFF0000, true);
	}
}

package com.puzzledrops.compassquadrants;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.geom.Arc2D;
import java.awt.geom.Line2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class CompassQuadrantsOverlay extends Overlay
{
	/**
	 * The plugin erases the game's own N from the compass sprite, so all four letters are ours.
	 * Bearings are clockwise from north, matching the letters.
	 */
	private static final String[] LETTERS = {"N", "E", "S", "W"};
	private static final int[] LETTER_BEARINGS = {0, 90, 180, 270};
	private static final int NORTH = 0;

	/**
	 * Fractions of the compass radius. The wedges fill it, so the north marker sits just beyond.
	 */
	private static final double LETTER_RADIUS = 0.62;
	private static final double MARKER_RADIUS = 1.09;
	private static final double MARKER_THICKNESS = 0.14;
	private static final double MARKER_ARC_DEGREES = 20;

	private final Client client;
	private final CompassQuadrantsConfig config;
	private final CompassQuadrantsPlugin plugin;

	@Inject
	private CompassQuadrantsOverlay(Client client, CompassQuadrantsConfig config, CompassQuadrantsPlugin plugin)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;

		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget compass = plugin.findCompassWidget();
		if (compass == null)
		{
			return null;
		}

		Rectangle bounds = compass.getBounds();
		if (bounds == null || bounds.isEmpty())
		{
			return null;
		}

		Point mouse = client.getMouseCanvasPosition();
		boolean hovered = mouse != null && bounds.contains(mouse.getX(), mouse.getY());

		WedgeGuideMode mode = config.wedgeGuides();
		boolean drawGuides = mode == WedgeGuideMode.ALWAYS || (mode == WedgeGuideMode.ON_HOVER && hovered);
		boolean drawHighlight = hovered && config.highlightHoveredWedge();
		boolean drawLetters = config.showCompassLetters();
		// With the face held still, the rim marker is the only thing left showing which way is north.
		boolean drawMarker = !config.rotateWithCompass();

		if (!drawGuides && !drawHighlight && !drawLetters && !drawMarker)
		{
			return null;
		}

		double cx = bounds.getCenterX();
		double cy = bounds.getCenterY();
		double radius = Math.min(bounds.getWidth(), bounds.getHeight()) / 2.0;

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		if (drawHighlight)
		{
			highlightWedge(graphics, cx, cy, radius, plugin.quadrantAt(bounds, mouse));
		}

		if (drawGuides)
		{
			drawDividers(graphics, cx, cy, radius);
		}

		if (drawMarker)
		{
			drawNorthMarker(graphics, cx, cy, radius);
		}

		if (drawLetters)
		{
			drawLetters(graphics, cx, cy, radius);
		}

		return null;
	}

	/**
	 * Shades the wedge that would be picked, so the mapping is obvious before committing to a click.
	 */
	private void highlightWedge(Graphics2D graphics, double cx, double cy, double radius, int quadrant)
	{
		double endBearing = quadrant * 90 + 45 + plugin.bearingOffset();

		graphics.setColor(config.highlightColor());
		graphics.fill(new Arc2D.Double(
			cx - radius, cy - radius, radius * 2, radius * 2,
			90 - endBearing, 90, Arc2D.PIE));
	}

	private void drawDividers(Graphics2D graphics, double cx, double cy, double radius)
	{
		double offset = plugin.bearingOffset();

		graphics.setColor(config.guideColor());
		graphics.setStroke(new BasicStroke(1f));

		for (int i = 0; i < 4; i++)
		{
			double bearing = Math.toRadians(i * 90 + 45 + offset);
			graphics.draw(new Line2D.Double(
				cx, cy,
				cx + radius * Math.sin(bearing),
				cy - radius * Math.cos(bearing)));
		}
	}

	/**
	 * A slice of the rim sitting outside the wedges, tracking true north while the face is frozen.
	 */
	private void drawNorthMarker(Graphics2D graphics, double cx, double cy, double radius)
	{
		double r = radius * MARKER_RADIUS;
		double startBearing = plugin.compassRotation() + MARKER_ARC_DEGREES / 2;

		graphics.setColor(config.northMarkerColor());
		graphics.setStroke(new BasicStroke((float) (radius * MARKER_THICKNESS), BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
		graphics.draw(new Arc2D.Double(
			cx - r, cy - r, r * 2, r * 2,
			90 - startBearing, MARKER_ARC_DEGREES, Arc2D.OPEN));
	}

	private void drawLetters(Graphics2D graphics, double cx, double cy, double radius)
	{
		// The letters label the wedges, so they hold still whenever the wedges do.
		double rotation = plugin.bearingOffset();
		double letterRadius = radius * LETTER_RADIUS;

		graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, (int) Math.max(8, radius * 0.5)));

		AffineTransform original = graphics.getTransform();

		for (int i = 0; i < LETTERS.length; i++)
		{
			double bearing = Math.toRadians(LETTER_BEARINGS[i] + rotation);
			double lx = cx + letterRadius * Math.sin(bearing);
			double ly = cy - letterRadius * Math.cos(bearing);

			graphics.translate(lx, ly);
			// Tilt each glyph with the disc, the same way the game's own N tilts.
			graphics.rotate(Math.toRadians(rotation));

			int width = graphics.getFontMetrics().stringWidth(LETTERS[i]);
			int height = graphics.getFontMetrics().getAscent();

			graphics.setColor(i == NORTH ? config.northLetterColor() : config.letterColor());
			graphics.drawString(LETTERS[i], -width / 2, height / 2);

			graphics.setTransform(original);
		}
	}
}

package com.puzzledrops.compassquadrants;

import com.google.inject.Provides;
import java.awt.Rectangle;
import java.util.Arrays;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.SpritePixels;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Compass Quadrants",
	description = "Left-click a wedge of the compass to face that direction",
	tags = {"compass", "camera", "direction", "north", "south", "east", "west"}
)
public class CompassQuadrantsPlugin extends Plugin
{
	/**
	 * The compass is a different component in each client layout, and only one is loaded at a time.
	 */
	private static final int[] COMPASS_WIDGET_IDS = {
		InterfaceID.Toplevel.COMPASSCLICK,
		InterfaceID.ToplevelOsrsStretch.COMPASSCLICK,
		InterfaceID.ToplevelPreEoc.COMPASSCLICK,
		InterfaceID.ToplevelOsm.COMPASSCLICK,
	};

	/**
	 * Indexed by quadrant, clockwise from north. These options are supplied by the game itself.
	 */
	private static final String[] LOOK_OPTIONS = {"Look North", "Look East", "Look South", "Look West"};

	/**
	 * {@link Client#getCameraYaw()} is measured in JAU14, so a full revolution is 2^14 units.
	 */
	private static final double DEGREES_PER_JAU = 360.0 / 16384.0;

	/**
	 * Where the N sits on the face, as fractions of the radius, and how far a pixel must stray from
	 * the background model to count as part of the letter rather than as artwork.
	 */
	private static final double LETTER_INNER_EDGE = 0.35;
	private static final double LETTER_OUTER_EDGE = 0.86;
	private static final double LETTER_SECTOR_DEGREES = 35;
	private static final int LETTER_DIFFERENCE = 60;

	@Inject
	private Client client;

	@Inject
	private CompassQuadrantsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CompassQuadrantsOverlay overlay;

	@Inject
	private ClientThread clientThread;

	private String lastSwapped;
	private SpritePixels originalCompass;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		clientThread.invoke(this::syncCompassSprite);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		lastSwapped = null;
		clientThread.invoke(this::restoreCompass);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// The sprite cache is repopulated on load, so the override has to be reapplied.
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invoke(this::syncCompassSprite);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CompassQuadrantsConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invoke(this::syncCompassSprite);
		}
	}

	/**
	 * Installs or removes the letterless compass depending on the current config. Returns false
	 * while the sprite cache is not yet loaded so {@link ClientThread} will retry.
	 */
	private boolean syncCompassSprite()
	{
		if (!config.showCompassLetters())
		{
			restoreCompass();
			return true;
		}

		if (originalCompass == null)
		{
			SpritePixels[] sprites = client.getSprites(client.getIndexSprites(), SpriteID.COMPASS, 0);
			if (sprites == null || sprites.length == 0 || sprites[0] == null)
			{
				return false;
			}

			originalCompass = sprites[0];
		}

		client.setCompass(withoutNorthLetter(originalCompass));
		return true;
	}

	private boolean restoreCompass()
	{
		if (originalCompass != null)
		{
			client.setCompass(originalCompass);
		}

		return true;
	}

	/**
	 * Erases the N without disturbing the needle or the tick marks. The face is a radial gradient,
	 * so the median colour at each radius reconstructs the background the letter is sitting on;
	 * anything in the northern sector that strays far enough from that model is the letter.
	 */
	private SpritePixels withoutNorthLetter(SpritePixels compass)
	{
		int width = compass.getWidth();
		int height = compass.getHeight();
		int[] source = compass.getPixels();
		int[] pixels = source.clone();

		double cx = (width - 1) / 2.0;
		double cy = (height - 1) / 2.0;
		double half = Math.min(cx, cy);
		int bins = (int) Math.ceil(Math.hypot(cx, cy)) + 1;

		int[] counts = new int[bins];
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				counts[radiusOf(x, y, cx, cy)]++;
			}
		}

		int[][] reds = new int[bins][];
		int[][] greens = new int[bins][];
		int[][] blues = new int[bins][];
		for (int i = 0; i < bins; i++)
		{
			reds[i] = new int[counts[i]];
			greens[i] = new int[counts[i]];
			blues[i] = new int[counts[i]];
		}

		int[] next = new int[bins];
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				int bin = radiusOf(x, y, cx, cy);
				int rgb = source[y * width + x];
				int at = next[bin]++;
				reds[bin][at] = (rgb >> 16) & 0xFF;
				greens[bin][at] = (rgb >> 8) & 0xFF;
				blues[bin][at] = rgb & 0xFF;
			}
		}

		for (int i = 0; i < bins; i++)
		{
			Arrays.sort(reds[i]);
			Arrays.sort(greens[i]);
			Arrays.sort(blues[i]);
		}

		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				double dx = x - cx;
				double dy = y - cy;
				double distance = Math.hypot(dx, dy);

				if (distance < half * LETTER_INNER_EDGE || distance > half * LETTER_OUTER_EDGE
					|| Math.abs(Math.toDegrees(Math.atan2(dx, -dy))) > LETTER_SECTOR_DEGREES)
				{
					continue;
				}

				int bin = radiusOf(x, y, cx, cy);
				int middle = counts[bin] / 2;
				int index = y * width + x;
				int rgb = source[index];

				int difference = Math.abs(((rgb >> 16) & 0xFF) - reds[bin][middle])
					+ Math.abs(((rgb >> 8) & 0xFF) - greens[bin][middle])
					+ Math.abs((rgb & 0xFF) - blues[bin][middle]);

				if (difference > LETTER_DIFFERENCE)
				{
					pixels[index] = (rgb & 0xFF000000)
						| (reds[bin][middle] << 16) | (greens[bin][middle] << 8) | blues[bin][middle];
				}
			}
		}

		return client.createSpritePixels(pixels, width, height);
	}

	private static int radiusOf(int x, int y, double cx, double cy)
	{
		return (int) Math.round(Math.hypot(x - cx, y - cy));
	}

	@Provides
	CompassQuadrantsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CompassQuadrantsConfig.class);
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		Widget compass = findCompassWidget();
		if (compass == null)
		{
			return;
		}

		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null)
		{
			return;
		}

		Rectangle bounds = compass.getBounds();
		if (bounds == null || !bounds.contains(mouse.getX(), mouse.getY()))
		{
			lastSwapped = null;
			return;
		}

		String wanted = LOOK_OPTIONS[quadrantAt(bounds, mouse)];

		if (!wanted.equals(lastSwapped))
		{
			lastSwapped = wanted;
			log.debug("{} (yaw={}, rotation={}deg, wedgeOffset={}deg)",
				wanted, client.getCameraYaw(), compassRotation(), bearingOffset());
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();

		// Search from the top down; the last matching index is what is top-most on the menu.
		for (int i = entries.length - 1; i >= 0; i--)
		{
			if (wanted.equals(Text.removeTags(entries[i].getOption())))
			{
				swap(menu, entries, i, entries.length - 1);
				return;
			}
		}
	}

	Widget findCompassWidget()
	{
		for (int id : COMPASS_WIDGET_IDS)
		{
			Widget widget = client.getWidget(id);
			if (widget != null && !widget.isHidden())
			{
				return widget;
			}
		}

		return null;
	}

	/**
	 * Returns the quadrant the mouse falls in, indexed clockwise from north. The wedges are split
	 * along the diagonals, so each cardinal direction sits at the centre of its own wedge.
	 */
	int quadrantAt(Rectangle bounds, Point mouse)
	{
		double dx = mouse.getX() - bounds.getCenterX();
		double dy = mouse.getY() - bounds.getCenterY();

		// Screen-space bearing: 0 is straight up, increasing clockwise.
		double screenBearing = Math.toDegrees(Math.atan2(dx, -dy));

		// Offset by half a wedge so the boundaries land on the diagonals rather than the cardinals.
		double angle = (screenBearing - bearingOffset() + 45) % 360;
		if (angle < 0)
		{
			angle += 360;
		}

		return (int) (angle / 90);
	}

	/**
	 * How far clockwise the compass face is drawn on screen. Camera yaw increases anticlockwise from
	 * north, so north is drawn at this bearing and a world direction W appears at W + rotation.
	 */
	double compassRotation()
	{
		return client.getCameraYaw() * DEGREES_PER_JAU;
	}

	/**
	 * The rotation applied to the wedges, which the user can opt out of to keep north at the top.
	 * The compass letters deliberately ignore this, as they label the compass face itself.
	 */
	double bearingOffset()
	{
		return config.rotateWithCompass() ? compassRotation() : 0;
	}

	private void swap(Menu menu, MenuEntry[] entries, int index1, int index2)
	{
		if (index1 == index2)
		{
			return;
		}

		MenuEntry entry1 = entries[index1], entry2 = entries[index2];
		entries[index1] = entry2;
		entries[index2] = entry1;

		if (entry1.getType() == MenuAction.CC_OP_LOW_PRIORITY)
		{
			entry1.setType(MenuAction.CC_OP);
		}

		if (entry2.getType() == MenuAction.CC_OP_LOW_PRIORITY)
		{
			entry2.setType(MenuAction.CC_OP);
		}

		menu.setMenuEntries(entries);
	}
}

package com.puzzledrops.compassquadrants;

public enum WedgeGuideMode
{
	ALWAYS("Always"),
	ON_HOVER("On hover"),
	NEVER("Never");

	private final String label;

	WedgeGuideMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.puzzledrops.compassquadrants;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CompassQuadrantsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CompassQuadrantsPlugin.class);
		RuneLite.main(args);
	}
}
